 "content": "def transform(grid):
    """Extend a periodic sequence of diagonal color bands (column-row offsets)."""
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h or not w:
        return [row[:] for row in grid]
    samples = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                offset = c - r
                if offset in samples and samples[offset] != color:
                    raise ValueError("conflicting colors on a diagonal")
                samples[offset] = color
    if not samples:
        return [row[:] for row in grid]

    period = None
    phases = None
    for p in range(1, h + w + 1):
        mapping = {}
        consistent = True
        for offset, color in samples.items():
            phase = offset % p
            if phase in mapping and mapping[phase] != color:
                consistent = False
                break
            mapping[phase] = color
        if consistent:
            period, phases = p, mapping
            break
    if period is None:
        raise ValueError("no consistent diagonal period")
    return [[phases[(c - r) % period] for c in range(w)] for r in range(h)]

